package org.springframework.samples.petclinic.rest.function.owner;

import java.net.URI;

import net.officefloor.plugin.variable.Val;
import net.officefloor.web.ObjectResponse;
import org.springframework.http.ResponseEntity;
import org.springframework.samples.petclinic.mapper.OwnerMapper;
import org.springframework.samples.petclinic.model.Owner;
import org.springframework.samples.petclinic.repository.OwnerRepository;
import org.springframework.samples.petclinic.rest.dto.OwnerDto;

public class RespondWithOwnerCreated {

    public void service(@Val Owner owner, OwnerRepository ownerRepository, OwnerMapper ownerMapper,
            ObjectResponse<ResponseEntity<OwnerDto>> response) {
        OwnerDto dto = ownerMapper.toOwnerDto(owner);
        dto.setBulkSignupWarning(DailyOwnerRegistrations.bulkSignupWarning(ownerRepository));
        response.send(ResponseEntity.created(URI.create("/api/owners/" + owner.getId())).body(dto));
    }
}
===DefaultOwnerRegistrationDate===
package org.springframework.samples.petclinic.rest.function.owner;

import java.time.LocalDate;

import net.officefloor.plugin.variable.Val;
import org.springframework.samples.petclinic.model.Owner;

/**
 * Establishes a new owner's effective registration date: the date supplied in the request, or the
 * server's current date when the request omits it. The effective date must fall on a business day,
 * so a Saturday or Sunday — whether supplied or defaulted — rolls forward to the next Monday (see
 * {@link BusinessDay}). Runs after {@link BuildOwner} maps the request and before
 * {@link AssignOwnerMembershipNumber} (which derives its year segment from this value) and
 * {@link SaveOwner} persists it.
 */
public class DefaultOwnerRegistrationDate {

    public void service(@Val Owner owner) {
        LocalDate effective = owner.getRegistrationDate() == null ? LocalDate.now()
                : owner.getRegistrationDate();
        owner.setRegistrationDate(BusinessDay.rollForward(effective));
    }
}
===ValidateOwnerRegistrationDate===
package org.springframework.samples.petclinic.rest.function.owner;

import java.time.LocalDate;

import net.officefloor.plugin.variable.Val;
import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
import org.springframework.samples.petclinic.rest.escalation.FutureRegistrationDateException;

/**
 * Validates the owner's registrationDate WHEN PRESENT, reading the published request body. An
 * absent date is accepted (it defaults to the server date later, see
 * {@link DefaultOwnerRegistrationDate}). A supplied date must not be later than the server's current
 * date; a future date is rejected with 400 via {@link FutureRegistrationDateException}.
 */
public class ValidateOwnerRegistrationDate {

    public void service(@Val OwnerFieldsDto request) throws FutureRegistrationDateException {
        LocalDate supplied = request.getRegistrationDate();
        if (supplied != null && supplied.isAfter(LocalDate.now())) {
            throw new FutureRegistrationDateException(supplied);
        }
    }
}
