1	package org.springframework.samples.petclinic.mapper;
2	
3	import org.jspecify.annotations.NonNull;
4	import org.mapstruct.Mapper;
5	import org.mapstruct.Mapping;
6	import org.springframework.data.domain.Page;
7	import org.springframework.samples.petclinic.model.Owner;
8	import org.springframework.samples.petclinic.rest.dto.OwnerDto;
9	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
10	import org.springframework.samples.petclinic.rest.dto.OwnerPageDto;
11	
12	import java.util.Collection;
13	import java.util.List;
14	
15	/**
16	 * Maps Owner &amp; OwnerDto using Mapstruct
17	 */
18	@Mapper(uses = PetMapper.class)
19	public abstract class OwnerMapper {
20	
21	    @Mapping(target = "displayName",
22	            expression = "java(owner.getLastName() + \", \" + owner.getFirstName())")
23	    @Mapping(target = "initials",
24	            expression = "java(Character.toUpperCase(owner.getFirstName().charAt(0)) + \".\" + Character.toUpperCase(owner.getLastName().charAt(0)) + \".\")")
25	    @Mapping(target = "membershipLevel",
26	            expression = "java(membershipLevel(owner))")
27	    @Mapping(target = "locality",
28	            expression = "java(org.springframework.samples.petclinic.rest.function.common.Localities.regionOf(owner.getCustomerCode()))")
29	    @Mapping(target = "contactPreference",
30	            expression = "java(contactPreference(owner))")
31	    @Mapping(target = "identityKey",
32	            expression = "java(org.springframework.samples.petclinic.rest.function.owner.OwnerIdentityKey.of(owner))")
33	    @Mapping(target = "checkDigit",
34	            expression = "java(checkDigit(owner))")
35	    @Mapping(target = "bulkSignupWarning", ignore = true)
36	    public abstract OwnerDto toOwnerDto(Owner owner);
37	
38	    public abstract Owner toOwner(OwnerDto ownerDto);
39	
40	    @Mapping(target = "id", ignore = true)
41	    @Mapping(target = "pets", ignore = true)
42	    public abstract Owner toOwner(OwnerFieldsDto ownerDto);
43	
44	    public abstract List<OwnerDto> toOwnerDtoCollection(Collection<Owner> ownerCollection);
45	
46	    public abstract Collection<Owner> toOwners(Collection<OwnerDto> ownerDtos);
47	
48	    public OwnerPageDto toOwnerPageDto(@NonNull Page<Owner> ownerPage) {
49	        OwnerPageDto ownerPageDto = new OwnerPageDto();
50	        ownerPageDto.setContent(toOwnerDtoCollection(ownerPage.getContent()));
51	        ownerPageDto.setPage(ownerPage.getNumber());
52	        ownerPageDto.setSize(ownerPage.getSize());
53	        ownerPageDto.setTotalElements(ownerPage.getTotalElements());
54	        ownerPageDto.setTotalPages(ownerPage.getTotalPages());
55	        return ownerPageDto;
56	    }
57	
58	    /**
59	     * Derive the owner's membership level, a number from 1 to 3 fixed at creation. Starts at 1,
60	     * plus 1 when an email is present, plus 1 when {@code namesakeCount} is 0, capped at 3
61	     * (level 4 is reserved for tenure).
62	     */
63	    protected Integer membershipLevel(Owner owner) {
64	        int level = 1;
65	        if (owner.getEmail() != null && !owner.getEmail().isEmpty()) {
66	            level++;
67	        }
68	        if (owner.getNamesakeCount() != null && owner.getNamesakeCount().intValue() == 0) {
69	            level++;
70	        }
71	        return Math.min(level, 3);
72	    }
73	
74	    /**
75	     * Derive the owner's preferred contact channel: {@code EMAIL} when an email is present,
76	     * otherwise {@code PHONE}.
77	     */
78	    protected String contactPreference(Owner owner) {
79	        return (owner.getEmail() != null && !owner.getEmail().isEmpty()) ? "EMAIL" : "PHONE";
80	    }
81	
82	    /**
83	     * Compute a single Luhn check digit (0-9) over the digits contained in the owner's
84	     * {@code customerCode}. Non-digit characters (such as the hyphen separators) are ignored.
85	     */
86	    protected Integer checkDigit(Owner owner) {
87	        String code = owner.getCustomerCode();
88	        if (code == null) {
89	            return null;
90	        }
91	        int sum = 0;
92	        boolean dbl = true;
93	        for (int i = code.length() - 1; i >= 0; i--) {
94	            char c = code.charAt(i);
95	            if (c < '0' || c > '9') {
96	                continue;
97	            }
98	            int d = c - '0';
99	            if (dbl) {
100	                d *= 2;
101	                if (d > 9) {
102	                    d -= 9;
103	                }
104	            }
105	            sum += d;
106	            dbl = !dbl;
107	        }
108	        return (10 - (sum % 10)) % 10;
109	    }
110	}
